# source me: strip tuning/test envs that would silently change behavior of a run (the run's ENV_TIPTOUR.txt records whatever remains)
for v in TIPTOUR_STALE_FRAME_GUARD TIPTOUR_STALE_FRAME_MAX TIPTOUR_STALE_TARGET_MAX TIPTOUR_VOICE_CTX TIPTOUR_ANSWER_WAIT_S TIPTOUR_CLIENT_FACTORY TIPTOUR_TEST_MODE TIPTOUR_NO_WARM TIPTOUR_USE_ATSPI TIPTOUR_USE_CDP TIPTOUR_STREAM TIPTOUR_CONFIG_DIR TIPTOUR_VOSK_MODEL FRAME_SETTLE TIPTOUR_CLICK_DETECT TIPTOUR_CLICK_BACKEND TIPTOUR_FAKE_DELAY TIPTOUR_CLICK_VALIDATE TIPTOUR_FAKE_TRIGGER TIPTOUR_FAKE_STEPS TIPTOUR_FAKE_TOOLCALL TIPTOUR_FAKE_LOG TIPTOUR_FAKE_LATE TIPTOUR_FAKE_EARLY_TC; do unset $v; done
export TIPTOUR_CONFIG_DIR=/nonexistent-tiptour-config
